  const q = auditQueue.get(repo) ?? { main, covers: [] };
  q.main = main;
  q.covers.push({ branch, mainAfter, at: Date.now() });
  auditQueue.set(repo, q);
  savePostLandAuditQueue(); // durable BEFORE the land path returns — see the file's comment
